use verus::*;

#[verifier::spec]
fn zeros_like(a: &Vec<i32>) -> Vec<i32> {
    // Ensure the input array is not null
    requires(a != &Vec::new());

    // Get the length of the input array
    let n = a.len();

    // Create a new vector of zeros with the same length as the input array
    let mut zeros = Vec::with_capacity(n);
    for _ in 0..n {
        zeros.push(0);
    }

    // Ensure the output has the same length as the input
    ensures(zeros.len() == n);

    // Ensure every element in the output is zero
    for i in 0..n {
        ensures(zeros[i] == 0);
    }

    // Ensure that adding the zeros array to any other array leaves it unchanged
    // This is a property we will assert
    assert_forall(|b: &Vec<i32>| {
        let m = b.len();
        requires(m == n);
        // Check that b + zeros == b
        for i in 0..m {
            assert(b[i] + zeros[i] == b[i]);
            assert(zeros[i] + b[i] == b[i]);
        }
    });

    // Return the zeros array
    zeros
}